'use strict';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let state,tab='pricing',dirty=false;
const messages={wrong_password:'Vale parool.',login_required:'Palun logi sisse.',stale_reload:'Andmeid muudeti teises aknas. Värskenda lehte enne uuesti salvestamist.',too_many_attempts:'Liiga palju katseid. Proovi 15 minuti pärast.',password_min_12:'Parool peab olema vähemalt 12 märki.',image_max_5mb:'Pilt võib olla kuni 5 MB.',invalid_image:'Kasuta JPG-, PNG- või WebP-pilti.',invalid_product:'Kontrolli toote nime, hinda, kogust ja pilte.',invalid_guest_threshold:'Külaliste piirid peavad olema kasvavad täisarvud 1–1000.'};
function status(s){$('#status').textContent=s}
async function api(path,method='GET',body){const r=await fetch('/api/admin/'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok){if(r.status===401&&path!=='login')showLogin();throw Error(messages[data.code]||'Salvestamine ei õnnestunud. Kontrolli sisestatud andmeid ja ühendust.')}return data}
function run(fn){return async e=>{e?.preventDefault();try{await fn(e)}catch(e){status(e.message)}}}
function showLogin(){$('#login').hidden=false;$('#workspace').hidden=true;$('#logout').hidden=true}
async function refresh(){state=await api('state');state.catalog.products.forEach(p=>p.images??=[]);$('#login').hidden=true;$('#workspace').hidden=false;$('#logout').hidden=false;dirty=false;render()}
$('#login-form').onsubmit=run(async()=>{await api('login','POST',{password:$('#password').value});$('#password').value='';await refresh();status('Oled sisse logitud.')});
$('#logout').onclick=run(async()=>{if(dirty&&!confirm('Salvestamata muudatused lähevad kaotsi. Jätkan?'))return;await api('logout','POST',{});dirty=false;showLogin();status('Oled välja logitud.')});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
$('#panel').addEventListener('input',()=>{dirty=true});
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=run(async()=>{if(dirty&&!confirm('Salvestamata muudatused lähevad kaotsi. Jätkan?'))return;tab=b.dataset.tab;await refresh();status('')}));
async function saveSettings(){const saved=await api('settings','PUT',state.settings);state.settings.revision=saved.revision;dirty=false;status('Muudatused salvestatud. Need on kodulehel nähtavad lehe värskendamisel.')}
const input=(label,id,value,type='text',extra='')=>`<label>${esc(label)}<input id="${id}" type="${type}" value="${esc(value)}" ${extra}></label>`;
function render(){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));({pricing,products,calendar,content,account})[tab]()}
const labels={packages:'Pulmapaketid',half:'Pool päeva',full:'Terve päev',coordination:'Koordineerimine',transport:'Transport',local:'Saaremaa / Muhumaa / Tartumaa',mainland:'Muu Mandri-Eesti',hiiu:'Hiiumaa',islands:'Muud saared',decor:'Dekoratsioonipaketid',mini:'Mini',midi:'Midi',maxi:'Maxi',extraHour:'Lisatund (€)',lateHour:'Tund pärast südaööd (€)',assistant:'Lisakoordinaator (€)',assistantFrom:'Lisakoordinaator alates külaliste arvust',visit:'Kohakülastus, transpordita (€)',website:'Pulmaleht (€)',dinner:'Pulmaeelne õhtusöök / külaline (€)',partyPoints:'Sünnipäevad ja suvepäevad',decorationPoints:'Muude sündmuste dekoratsioonid'};
function pricing(){const fields=[];function walk(o,path=[]){for(const [k,v]of Object.entries(o)){const p=[...path,k];if(typeof v==='number'){let name=p.map(x=>labels[x]||x).join(' · ');if(path[0]==='decor')name=p.slice(0,2).map(x=>labels[x]).join(' · ')+(k==='0'?' · baashind (€)':' · külalise kohta (€)');if(['partyPoints','decorationPoints'].includes(path[0]))name=labels[path[0]]+' · punkt '+(+path[1]+1)+(k==='0'?' · külalisi':' · hind (€)');fields.push({path:p,label:name,value:v})}else walk(v,p)}}walk(state.settings.pricing);$('#panel').innerHTML='<h2>Kalkulaatori hinnad</h2><p>Kõik summad eurodes. Käibemaksu ei lisata. Külaliste hinnapunktide vahe arvutatakse sujuvalt; üle viimase punkti jääb hind samaks.</p><form id="prices-form"><div class="admin-grid">'+fields.map((f,i)=>input(f.label,'price-'+i,f.value,'number','min="0" max="1000000" step="0.01" required')).join('')+'</div><button class="button">Salvesta hinnad</button></form>';$('#prices-form').onsubmit=run(async()=>{fields.forEach((f,i)=>{let o=state.settings.pricing;f.path.slice(0,-1).forEach(k=>o=o[k]);o[f.path.at(-1)]=+$('#price-'+i).value});await saveSettings()})}
async function upload(file){if(file.size>5*1024*1024)throw Error(messages.image_max_5mb);if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error(messages.invalid_image);const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});return (await api('upload','POST',{data})).url}
function products(){const ps=state.catalog.products;$('#panel').innerHTML='<h2>Renditooted</h2><p>36 tunni baashind. Lisapäev on 10% baashinnast. Toote peitmiseks määra laokoguseks 0; olemasolevad broneeringud säilivad.</p><div class="actions"><select id="product-select" aria-label="Toode">'+ps.map((p,i)=>`<option value="${i}">${esc(p.name.et)}</option>`).join('')+'</select><button id="add-product">Lisa toode</button></div><div id="product-edit"></div>';$('#product-select').onchange=()=>{readProduct();editProduct(+$('#product-select').value)};$('#add-product').onclick=()=>{readProduct();ps.push({id:'product-'+crypto.randomUUID(),category:'table',name:{et:'Uus toode',en:'New product'},description:{et:'',en:''},price:0,stock:0,images:[]});dirty=true;products();$('#product-select').value=ps.length-1;editProduct(ps.length-1)};if(ps.length)editProduct(0)}
let editingProduct=null;
function readProduct(){if(editingProduct===null||!$('#product-form'))return;const p=state.catalog.products[editingProduct];for(const l of ['et','en']){p.name[l]=$('#name-'+l).value;p.description[l]=$('#desc-'+l).value}p.category=$('#category').value;p.price=+$('#product-price').value;p.stock=+$('#stock').value}
function editProduct(i){editingProduct=i;const p=state.catalog.products[i];$('#product-edit').innerHTML='<form id="product-form"><div class="admin-grid">'+['et','en'].map(l=>input('Nimi ('+l.toUpperCase()+')','name-'+l,p.name[l],'text','maxlength="150" required')+`<label>Kirjeldus (${l.toUpperCase()})<textarea id="desc-${l}" maxlength="10000">${esc(p.description[l])}</textarea></label>`).join('')+`<label>Kategooria<select id="category"><option value="table">Lauakaunistused</option><option value="large">Suured dekoratsioonid</option><option value="clothes">Riided</option></select></label>`+input('Baashind (€)','product-price',p.price,'number','min="0" max="1000000" step="0.01" required')+input('Laokogus','stock',p.stock,'number','min="0" max="10000" step="1" required')+'</div><h3>Tootepildid</h3><p class="hint">Kuni 5 pilti, igaüks kuni 5 MB. JPG, PNG või WebP. Esimene pilt on kaanepilt.</p><div id="product-images" class="images"></div><label>Lisa pildid<input id="product-upload" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><button class="button">Salvesta renditooted</button></form>';$('#category').value=p.category;drawImages();$('#product-upload').onchange=run(async()=>{const files=[...$('#product-upload').files];if(p.images.length+files.length>5)throw Error('Ühele tootele saab lisada kuni 5 pilti.');readProduct();for(const file of files){p.images.push(await upload(file));dirty=true;drawImages()}$('#product-upload').value='';status('Pildid lisatud. Vajuta „Salvesta renditooted”.')});$('#product-form').onsubmit=run(async()=>{readProduct();await api('products','PUT',state.catalog);state.catalog.revision=(state.catalog.revision||0)+1;dirty=false;status('Renditooted salvestatud.');products()})}
function drawImages(){const p=state.catalog.products[editingProduct];$('#product-images').innerHTML=p.images.map((src,i)=>`<figure><img src="${esc(src)}" alt="Tootepilt ${i+1}"><button type="button" data-remove="${i}">Eemalda</button>${i?`<button type="button" data-cover="${i}">Kaanepildiks</button>`:''}</figure>`).join('');document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{p.images.splice(+b.dataset.remove,1);dirty=true;drawImages()});document.querySelectorAll('[data-cover]').forEach(b=>b.onclick=()=>{p.images.unshift(p.images.splice(+b.dataset.cover,1)[0]);dirty=true;drawImages()})}
function calendar(){$('#panel').innerHTML='<h2>Kalendrite haldus</h2><p>Märgi suletud kuupäevad, kaasa arvatud esimene ja viimane päev. Rendis blokeeritakse ka perioodid, mille kasutus- või ettevalmistusaeg suletud päevaga kattub. Olemasolevaid broneeringuid ei tühistata.</p><form id="closure-form" class="box"><div class="admin-grid"><label>Kalender<select id="closure-kind"><option value="event">Üritused</option><option value="rental">Renditooted</option></select></label><label>Renditoode<select id="closure-product" disabled><option value="all">Kõik renditooted</option>'+state.catalog.products.map(p=>`<option value="${p.id}">${esc(p.name.et)}</option>`).join('')+'</select></label>'+input('Alates','closure-from','','date','required')+input('Kuni (kaasa arvatud)','closure-to','','date','required')+'</div><button class="button">Märgi aeg hõivatuks</button></form><h3>Suletud ajad</h3><div id="closure-list"></div><h3>Rendibroneeringud</h3><div class="table-wrap"><table><thead><tr><th>Viide / toode</th><th>Kasutusaeg</th><th>Kogus</th><th>Kontakt</th></tr></thead><tbody>'+state.bookings.map(b=>`<tr><td>${esc(b.reference)}<br>${esc(state.catalog.products.find(p=>p.id===b.product_id)?.name.et||b.product_id)}</td><td>${new Date(b.start).toLocaleString('et-EE',{timeZone:'Europe/Tallinn'})}<br>${new Date(b.customer_end).toLocaleString('et-EE',{timeZone:'Europe/Tallinn'})}</td><td>${b.quantity}</td><td>${esc(b.name)}<br>${esc(b.email)}</td></tr>`).join('')+'</tbody></table></div>';$('#closure-kind').onchange=()=>$('#closure-product').disabled=$('#closure-kind').value!=='rental';$('#closure-list').innerHTML=state.closures.length?state.closures.map(c=>`<div class="box">${c.kind==='event'?'Üritused':esc(c.product_id==='all'?'Kõik renditooted':state.catalog.products.find(p=>p.id===c.product_id)?.name.et||c.product_id)} · ${c.from_date} – ${c.to_date} <button data-open="${c.id}">Ava aeg uuesti</button></div>`).join(''):'<p>Suletud aegu ei ole.</p>';$('#closure-form').onsubmit=run(async()=>{await api('closures','POST',{kind:$('#closure-kind').value,productId:$('#closure-product').value,from:$('#closure-from').value,to:$('#closure-to').value});await refresh();status('Aeg märgitud hõivatuks.')});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=run(async()=>{await api('closures','DELETE',{id:b.dataset.open});await refresh();status('Aeg taas avatud.')}))}
function content(){const l=state.settings.leader;$('#panel').innerHTML='<h2>Tekstid ja pildid</h2><form id="leader-form" class="box"><h3>Juhi tutvustus kontaktilehel</h3>'+input('Nimi','leader-name',l.name,'text','maxlength="100" required')+['et','en'].map(k=>`<label>Tutvustus (${k.toUpperCase()})<textarea id="leader-${k}" maxlength="10000">${esc(l[k])}</textarea></label>`).join('')+'<div id="leader-image" class="images">'+(l.image?`<img src="${esc(l.image)}" alt="Juhi portree">`:'<p>Portree pole lisatud.</p>')+'</div><label>Lisa või asenda portree<input id="leader-upload" type="file" accept="image/jpeg,image/png,image/webp"></label><button id="remove-leader" type="button">Eemalda portree</button><div class="actions"><button class="button">Salvesta tutvustus</button></div></form><div class="box"><h3>Avalehe suur pilt</h3><label>Asenda pilt<input id="hero-upload" type="file" accept="image/jpeg,image/png,image/webp"></label><p class="hint">Pilt salvestatakse kohe. Maksimum 5 MB.</p></div><div class="box"><h3>Lehtede tekstid</h3><p>Vali leht ja keel. Muuda all olevaid tekstilõike; hinnad ja tooted on eraldi vahelehtedel.</p><div class="admin-grid"><label>Leht<select id="text-page"><option value="/">Avaleht</option><option value="/services/">Teenused</option><option value="/rentals/">Rent</option><option value="/contact/">Kontakt</option><option value="/portfolio/">Portfoolio</option><option value="/portfolio/wedding/">Pulmalugu</option></select></label><label>Keel<select id="text-lang"><option value="et">Eesti</option><option value="en">English</option></select></label></div><button id="load-texts">Laadi lehe tekstid</button><iframe id="content-preview" title="Lehe eelvaade"></iframe><form id="text-form"><div id="text-fields"></div><button class="button" id="save-texts" hidden>Salvesta tekstid</button></form></div>';
 const capture=()=>{l.name=$('#leader-name').value;l.et=$('#leader-et').value;l.en=$('#leader-en').value};$('#leader-form').onsubmit=run(async()=>{capture();await saveSettings()});$('#leader-upload').onchange=run(async()=>{const f=$('#leader-upload').files[0];if(!f)return;l.image=await upload(f);dirty=true;$('#leader-image').innerHTML=`<img src="${esc(l.image)}" alt="Juhi portree">`;status('Pilt lisatud. Salvesta tutvustus.')});$('#remove-leader').onclick=()=>{l.image='';dirty=true;$('#leader-image').textContent='Portree eemaldatud. Salvesta tutvustus.'};$('#hero-upload').onchange=run(async()=>{const f=$('#hero-upload').files[0];if(!f)return;capture();state.settings.images['/wedding.jpg']=await upload(f);await saveSettings()});$('#load-texts').onclick=run(async()=>{const frame=$('#content-preview'),language=$('#text-lang').value;$('#save-texts').hidden=true;frame.contentWindow.eheReady=false;frame.src=$('#text-page').value+'?lang='+language;await new Promise((resolve,reject)=>{let n=0;const timer=setInterval(()=>{if(frame.contentWindow?.eheReady){clearInterval(timer);resolve()}else if(++n>150){clearInterval(timer);reject(Error('Eelvaate laadimine ebaõnnestus.'))}},100)});const nodes=frame.contentWindow.editableNodes(frame.contentDocument),keys=[...new Set(nodes.map(n=>n.eheOriginal||n.textContent))];$('#text-fields').innerHTML=keys.map((key,i)=>`<label><span class="original">${esc(key)}</span><textarea id="text-${i}" maxlength="10000">${esc(state.settings.texts[language][key]??key)}</textarea></label>`).join('');$('#save-texts').hidden=false;$('#text-form').onsubmit=run(async()=>{capture();keys.forEach((key,i)=>state.settings.texts[language][key]=$('#text-'+i).value);await saveSettings()})})}
function account(){$('#panel').innerHTML='<h2>Muuda parooli</h2><form id="password-form">'+input('Uus parool (vähemalt 12 märki)','new-password','','password','minlength="12" maxlength="200" autocomplete="new-password" required')+input('Korda uut parooli','repeat-password','','password','minlength="12" maxlength="200" autocomplete="new-password" required')+'<button class="button">Salvesta uus parool</button></form>';$('#password-form').onsubmit=run(async()=>{if($('#new-password').value!==$('#repeat-password').value)throw Error('Paroolid ei ühti.');await api('password','POST',{password:$('#new-password').value});dirty=false;showLogin();status('Parool muudetud. Logi uue parooliga sisse.')})}
refresh().catch(()=>showLogin());
